static void transpose4(const float*restrict x,float*restrict y,int n,const float*scale){
 for(int i=0;i<n;i+=4)for(int j=0;j<n;j+=4){
  T a=vld1q_f32(x+i*n+j),b=vld1q_f32(x+(i+1)*n+j),c=vld1q_f32(x+(i+2)*n+j),d=vld1q_f32(x+(i+3)*n+j);
  float32x4x2_t u=vtrnq_f32(a,b),v=vtrnq_f32(c,d);
  T z[4]={vcombine_f32(vget_low_f32(u.val[0]),vget_low_f32(v.val[0])),vcombine_f32(vget_low_f32(u.val[1]),vget_low_f32(v.val[1])),vcombine_f32(vget_high_f32(u.val[0]),vget_high_f32(v.val[0])),vcombine_f32(vget_high_f32(u.val[1]),vget_high_f32(v.val[1]))};
  for(int k=0;k<4;k++){if(scale)z[k]=vmulq_f32(z[k],vld1q_f32(scale+(j+k)*n+i));vst1q_f32(y+(j+k)*n+i,z[k]);}
 }
}
/* Band passes: 4 rows in lanes. Load a band transposed into a contiguous temp with vst4q (4 loads + 1 st4 per 4x4 block),
   run the column kernel with stride 4 on the temp, store transposed with vld4q (1 ld4 + 4 stores), optional scale table. */
static inline void band_load(const float*restrict a,int n,int k0,T*restrict t){
 for(int xb=0;xb<n;xb+=4){float32x4x4_t q;q.val[0]=vld1q_f32(a+(size_t)k0*n+xb);q.val[1]=vld1q_f32(a+(size_t)(k0+1)*n+xb);q.val[2]=vld1q_f32(a+(size_t)(k0+2)*n+xb);q.val[3]=vld1q_f32(a+(size_t)(k0+3)*n+xb);vst4q_f32((float*)(t+xb),q);}}
static inline void band_load_s(const float*restrict a,int n,int S,int k0,T*restrict t){
 for(int xb=0;xb<n;xb+=4){float32x4x4_t q;q.val[0]=vld1q_f32(a+(size_t)k0*S+xb);q.val[1]=vld1q_f32(a+(size_t)(k0+1)*S+xb);q.val[2]=vld1q_f32(a+(size_t)(k0+2)*S+xb);q.val[3]=vld1q_f32(a+(size_t)(k0+3)*S+xb);vst4q_f32((float*)(t+xb),q);}}
static inline void band_store_s(const T*restrict t,int n,int S,int k0,float*restrict y,const float*scale){
 for(int mb=0;mb<n;mb+=4){float32x4x4_t q=vld4q_f32((const float*)(t+mb));for(int r=0;r<4;r++){T v=q.val[r];if(scale)v=vmulq_f32(v,vld1q_f32(scale+(size_t)(k0+r)*n+mb));vst1q_f32(y+(size_t)(k0+r)*S+mb,v);}}}
static inline void pad_copy(const float*restrict x,float*restrict p,int n){for(int r=0;r<n;r++)memcpy(p+(size_t)r*(n+4),x+(size_t)r*n,(size_t)n*sizeof(float));}
static inline void band_store(const T*restrict t,int n,int k0,float*restrict y,const float*scale){
 for(int mb=0;mb<n;mb+=4){float32x4x4_t q=vld4q_f32((const float*)(t+mb));for(int r=0;r<4;r++){T v=q.val[r];if(scale)v=vmulq_f32(v,vld1q_f32(scale+(size_t)(k0+r)*n+mb));vst1q_f32(y+(size_t)(k0+r)*n+mb,v);}}}
static void vertical_f32(const float*restrict x,float*restrict y){T u[32],v[32];for(int col=0;col<32;col+=4){for(int k=0;k<32;k++)u[k]=vld1q_f32(x+k*32+col);one_f32(u,v);for(int k=0;k<32;k++)vst1q_f32(y+k*32+col,v[k]);}}
static void half_f32(const float*restrict x,float*restrict y,float*restrict a,float*restrict b){vertical_f32(x,a);transpose4(a,b,32,NULL);vertical_f32(b,y);}
static void bvertical_f32(const float*restrict x,float*restrict y,T*restrict w){for(int col=0;col<32;col+=4)col_f32(x+col,y+col,w);}
static void bhalf_f32(const float*restrict x,float*restrict y,float*restrict a,float*restrict b,T*restrict w){bvertical_f32(x,a,w);transpose4(a,b,32,NULL);bvertical_f32(b,y,w);}
static void bandline_f32(const float*restrict a,float*restrict y,const float*scale,T*restrict w){T*u=w,*v=w+32;for(int k0=0;k0<32;k0+=4){band_load(a,32,k0,u);one_f32(u,v);band_store(v,32,k0,y,scale);}}
static void bandblk_f32(const float*restrict a,float*restrict y,const float*scale,T*restrict w){T*u=w,*v=w+32;T*ws=w+2*32;for(int k0=0;k0<32;k0+=4){band_load(a,32,k0,u);col_f32s4((const float*)u,(float*)v,ws);band_store(v,32,k0,y,scale);}}
static void pvertical_f32(const float*restrict x,float*restrict y){T u[32],v[32];for(int col=0;col<32;col+=4){for(int k=0;k<32;k++)u[k]=vld1q_f32(x+k*36+col);one_f32(u,v);for(int k=0;k<32;k++)vst1q_f32(y+k*36+col,v[k]);}}
static void pbvertical_f32(const float*restrict x,float*restrict y,T*restrict w){for(int col=0;col<32;col+=4)col_f32p(x+col,y+col,w);}
static void pbandline_f32(const float*restrict a,float*restrict y,int So,const float*scale,T*restrict w){T*u=w,*v=w+32;for(int k0=0;k0<32;k0+=4){band_load_s(a,32,36,k0,u);one_f32(u,v);band_store_s(v,32,So,k0,y,scale);}}
static void b4cols_f32(const float*restrict x,float*restrict y,T*restrict w){for(int c=0;c<32;c++)col_f32b4(x+4*c,y+4*c,w);}
static void b4rows_f32(const float*restrict a,float*restrict y,const float*scale,T*restrict w){T*t=w;T*ws=w+32;for(int k=0;k<32;k++){col_f32s4(a+(size_t)k*132,(float*)t,ws);if(scale){for(int mm=0;mm<32;mm++)vst1q_f32(y+(size_t)k*132+4*mm,vmulq_n_f32(t[mm],scale[k*32+mm]));}else memcpy(y+(size_t)k*132,t,32*sizeof(T));}}
static void pbandblk_f32(const float*restrict a,float*restrict y,int So,const float*scale,T*restrict w){T*u=w,*v=w+32;T*ws=w+2*32;for(int k0=0;k0<32;k0+=4){band_load_s(a,32,36,k0,u);col_f32s4((const float*)u,(float*)v,ws);band_store_s(v,32,So,k0,y,scale);}}
static void vertical_t32(const float*restrict x,float*restrict y){T u[32],v[32];for(int col=0;col<32;col+=4){for(int k=0;k<32;k++)u[k]=vld1q_f32(x+k*32+col);one_t32(u,v);for(int k=0;k<32;k++)vst1q_f32(y+k*32+col,v[k]);}}
